import Foundation
import SwiftUI

/// Owns the ⌘F find-in-document state for a single markdown viewer window:
/// the query, the resolved matches (against the rendered plain-text
/// projection, not the raw markdown source), and which one is current.
///
/// Instantiated once per viewer window (`@StateObject`) so closing the find
/// bar and reopening it with ⌘F restores the last query, per the acceptance
/// criteria — `close()` only hides the bar, it never clears `query`.
///
/// The document is split into the same chunks `MarkdownDocumentColumn`
/// renders (see `MarkdownHeadingSections.chunks`), and matches are computed
/// per chunk against exactly the text that chunk's own parser highlights.
/// This keeps the counting corpus and the highlighting corpus identical by
/// construction — a single global `plainText` (as before chunking existed)
/// would include a collapsible heading's own text, which no chunk's parser
/// ever renders, shifting the global/local index mapping for every match
/// after the fold.
@MainActor
final class MarkdownFindState: ObservableObject {
    @Published var isActive: Bool = false
    @Published var query: String = "" {
        didSet {
            guard query != oldValue else { return }
            recomputeMatches()
        }
    }
    /// All matches, concatenated in document order across chunks. Documents
    /// without headings are a single chunk; documents with headings have
    /// one chunk per heading section (plus a leading prefix if the source
    /// does not start with a heading).
    @Published private(set) var matches: [Range<Int>] = []
    @Published private(set) var currentIndex: Int?
    /// Bumped on every change that should re-paint highlights and/or
    /// re-reveal the current match. A dedicated counter is used instead of
    /// observing `matches`/`currentIndex` directly: a new query can still
    /// resolve its first hit to index 0 same as the previous query's current
    /// index, in which case `currentIndex` doesn't change value even though
    /// the underlying match (and its position in the document) did — an
    /// `onChange(of: currentIndex)` would miss that transition.
    @Published private(set) var navigationNonce: Int = 0

    private struct ChunkCorpus {
        let chunk: MarkdownDocumentChunk
        /// The rendered plain-text projection of exactly this chunk's own
        /// text (its body when collapsible — never the heading label, which
        /// `CollapsibleMarkdownSection` renders as a separate plain `Text`,
        /// not through this chunk's parser).
        let plainText: String
    }

    private var chunkCorpora: [ChunkCorpus] = []
    /// Per-chunk matches, recomputed on every query change against the
    /// already-cached `chunkCorpora[i].plainText` — never re-parses markdown.
    private var matchesByChunk: [[Range<Int>]] = []
    /// Global index (into the flattened `matches`) of each chunk's first
    /// match; used to translate `currentIndex` into a chunk-local index.
    private var chunkGlobalStartIndex: [Int] = []
    /// Cumulative plain-text length of all chunks before this one, used only
    /// to derive an approximate whole-document scroll fraction.
    private var chunkPlainTextOffset: [Int] = []
    private var totalPlainTextLength: Int = 0

    /// "N of M" (1-indexed), "Not found" for a non-empty query with zero
    /// hits, or empty when the query itself is empty.
    var counterText: String {
        guard !query.isEmpty else { return "" }
        guard !matches.isEmpty, let currentIndex else { return "Not found" }
        return "\(currentIndex + 1) of \(matches.count)"
    }

    /// The chunk index the current match belongs to, or `nil` if there is no
    /// current match.
    var currentChunkIndex: Int? {
        guard let currentIndex else { return nil }
        for (index, start) in chunkGlobalStartIndex.enumerated() {
            let count = matchesByChunk[index].count
            if currentIndex >= start && currentIndex < start + count { return index }
        }
        return nil
    }

    /// The heading of the collapsible chunk the current match belongs to, if
    /// any — the caller uses this to auto-expand a folded section that holds
    /// the match the user just navigated to, since a collapsed section's body
    /// isn't in the view hierarchy at all and would otherwise silently
    /// consume a find-bar index without ever being visible.
    var currentCollapsibleHeadingToExpand: String? {
        guard let index = currentChunkIndex, chunkCorpora.indices.contains(index) else { return nil }
        guard case .collapsible(let heading, _) = chunkCorpora[index].chunk else { return nil }
        return heading
    }

    /// An approximate whole-document scroll fraction (0...1) for the current
    /// match, derived from the cumulative plain-text length of chunks before
    /// it plus its own local offset.
    var currentMatchScrollFraction: Double? {
        guard let index = currentChunkIndex, let currentIndex else { return nil }
        let localIndex = currentIndex - chunkGlobalStartIndex[index]
        guard matchesByChunk[index].indices.contains(localIndex) else { return nil }
        let globalOffset = chunkPlainTextOffset[index] + matchesByChunk[index][localIndex].lowerBound
        return Double(globalOffset) / Double(max(totalPlainTextLength, 1))
    }

    /// Re-derives the search corpus from the (possibly newly-loaded) source,
    /// split into the same heading chunks rendering uses
    /// (see `MarkdownHeadingSections.chunks`). Uses the identical
    /// projection comments anchor against (`CommentProjection.plainText`) so
    /// search hits and comment highlights never disagree about where text
    /// lives in the rendered document.
    func updateSource(_ source: String, baseURL: URL?, collapsibleHeadings: Set<String> = []) {
        let chunks = MarkdownHeadingSections.chunks(in: source, collapsibleHeadings: collapsibleHeadings)
        chunkCorpora = chunks.map { chunk in
            ChunkCorpus(chunk: chunk, plainText: CommentProjection.plainText(for: chunk.renderedText, baseURL: baseURL))
        }
        recomputeMatches()
    }

    /// The local matches for one rendered chunk, plus that chunk's current
    /// match index (if the globally current match falls inside it) — for
    /// `MarkdownDocumentColumn` to build that chunk's own
    /// `SearchHighlightingMarkdownParser` without recomputing anything.
    func chunkMatches(_ index: Int) -> (matches: [Range<Int>], currentLocalIndex: Int?) {
        guard matchesByChunk.indices.contains(index) else { return ([], nil) }
        let local = matchesByChunk[index]
        guard let currentIndex else { return (local, nil) }
        let localIndex = currentIndex - chunkGlobalStartIndex[index]
        return (local, (localIndex >= 0 && localIndex < local.count) ? localIndex : nil)
    }

    func open() {
        isActive = true
        navigationNonce &+= 1
    }

    func close() {
        isActive = false
        navigationNonce &+= 1
    }

    func selectNext() {
        guard !matches.isEmpty else { return }
        currentIndex = ((currentIndex ?? -1) + 1) % matches.count
        navigationNonce &+= 1
    }

    func selectPrevious() {
        guard !matches.isEmpty else { return }
        currentIndex = ((currentIndex ?? 0) - 1 + matches.count) % matches.count
        navigationNonce &+= 1
    }

    private func recomputeMatches() {
        matchesByChunk = chunkCorpora.map { query.isEmpty ? [] : MarkdownSearch.findMatches(of: query, in: $0.plainText) }

        chunkGlobalStartIndex = []
        chunkPlainTextOffset = []
        var globalCount = 0
        var plainOffset = 0
        for (index, corpus) in chunkCorpora.enumerated() {
            chunkGlobalStartIndex.append(globalCount)
            chunkPlainTextOffset.append(plainOffset)
            globalCount += matchesByChunk[index].count
            plainOffset += corpus.plainText.count
        }
        totalPlainTextLength = plainOffset

        matches = matchesByChunk.flatMap { $0 }
        currentIndex = matches.isEmpty ? nil : 0
        navigationNonce &+= 1
    }
}

import Foundation
import os.log
import SwiftUI
import Textual

/// Diagnostic channel for comment-anchor resolution. Every anchor logs whether it
/// resolved to a rendered range, the strategy that matched (exact vs. whitespace-
/// tolerant), the resolved character range, and whether a highlight was emitted —
/// or, on failure, why no span matched. This is the verbose-logging debug affordance
/// requested on the "comment anchors invisible" bug: stream it live with
///
///   log stream --predicate 'subsystem == "com.boss.markdown" AND category == "comment-highlight"' --style compact
private let highlightLog = Logger(subsystem: "com.boss.markdown", category: "comment-highlight")

/// A MarkupParser that wraps Textual's built-in markdown parser and applies a yellow
/// background to the text each comment is anchored to, and an orange background to the
/// actively flashing anchor when a comment is clicked.
///
/// Each anchor is a W3C `TextQuoteSelector` (`{exact, prefix, suffix}`): two comments on
/// two different occurrences of the same word disambiguate by surrounding context rather
/// than a stored occurrence index, so a highlight survives doc edits that do not touch the
/// text around the anchor.
///
/// ## Why two attributes per highlight
///
/// The highlight sets BOTH a `backgroundColor` and — on any inline-code run inside the
/// anchored range — a colored `underlineStyle`. The background alone is not enough: the
/// inline styles give inline code spans their own `backgroundColor`, and Textual's
/// `WithInlineStyle` merges that in with `mergePolicy: .keepNew`, which *overwrites* the
/// comment's background on exactly those runs. In editorial mode, that color is also the
/// fallback for paths where the canvas decoration that paints the inline-code box behind
/// the text has no layout. The colored underline is the appearance-independent guarantee:
/// it is applied after the background and is never touched by the inline style.
@MainActor
struct HighlightingMarkdownParser: MarkupParser {
    var highlightedAnchors: [CommentAnchor]
    var flashingAnchor: CommentAnchor?
    var baseURL: URL?

    private static let yellowColor = Color(nsColor: NSColor.systemYellow).opacity(0.45)
    private static let orangeColor = Color(nsColor: NSColor.systemOrange).opacity(0.55)
    // Stronger, mostly-opaque variants used for the underline marker so it stays visible
    // even when an inline-code background overwrites the translucent fill.
    private static let yellowUnderline = Color(nsColor: NSColor.systemYellow).opacity(0.9)
    private static let orangeUnderline = Color(nsColor: NSColor.systemOrange).opacity(0.9)

    init(highlightedAnchors: [CommentAnchor], flashingAnchor: CommentAnchor? = nil, baseURL: URL? = nil) {
        self.highlightedAnchors = highlightedAnchors
        self.flashingAnchor = flashingAnchor
        self.baseURL = baseURL
    }

    func attributedString(for input: String) throws -> AttributedString {
        var result = try AttributedStringMarkdownParser.markdown(baseURL: baseURL).attributedString(for: input)
        let plain = String(result.characters)

        highlightLog.debug(
            "resolve start: anchors=\(highlightedAnchors.count, privacy: .public) flashing=\(flashingAnchor != nil, privacy: .public) renderedChars=\(plain.count, privacy: .public)"
        )

        for (index, anchor) in highlightedAnchors.enumerated() where !anchor.exact.isEmpty {
            highlight(
                anchor: anchor,
                fill: Self.yellowColor,
                underline: Self.yellowUnderline,
                label: "anchor[\(index)]",
                in: &result,
                plain: plain
            )
        }
        if let flashing = flashingAnchor, !flashing.exact.isEmpty {
            highlight(
                anchor: flashing,
                fill: Self.orangeColor,
                underline: Self.orangeUnderline,
                label: "flash",
                in: &result,
                plain: plain
            )
        }

        return result
    }

    /// Highlights the occurrence of `anchor.exact` disambiguated by its
    /// `prefix`/`suffix` context (see [`resolveRange`]).
    ///
    /// Matching is whitespace-tolerant: a run of whitespace in `exact` matches a run of
    /// one-or-more whitespace characters in the rendered text. This is what makes a
    /// multi-line selection resolve — the pasteboard text captured when the comment was
    /// created often uses `\n` where the rendered projection uses a single space (or
    /// vice-versa), so an exact `range(of:)` would silently fail to match.
    ///
    /// If `exact` no longer appears (e.g. the document changed since the comment was
    /// created), no highlight is applied — a silent no-op is safer than highlighting the
    /// wrong span. The engine's `comments_resolve` is the authoritative resolver and will
    /// have flipped such a comment to `orphaned`; this local paint is a best-effort visual.
    private func highlight(
        anchor: CommentAnchor,
        fill: Color,
        underline: Color,
        label: String,
        in result: inout AttributedString,
        plain: String
    ) {
        let preview = anchor.exact.prefix(48).replacingOccurrences(of: "\n", with: "⏎")

        guard let matchRange = Self.resolveRange(for: anchor, in: plain) else {
            highlightLog.error(
                "\(label, privacy: .public): NO MATCH for exact=\"\(preview, privacy: .public)\""
            )
            return
        }

        let startOffset = plain.distance(from: plain.startIndex, to: matchRange.lowerBound)
        let matchLength = plain.distance(from: matchRange.lowerBound, to: matchRange.upperBound)
        // Map plain-text character offsets onto result.characters. Character-level
        // distances (not UTF-16 offsets) keep the mapping correct for non-BMP code
        // points such as emoji that span two UTF-16 units; `plain` is itself
        // `String(result.characters)`, so the two index spaces are 1:1 by construction.
        let startIdx = result.characters.index(result.characters.startIndex, offsetBy: startOffset)
        let endIdx = result.characters.index(startIdx, offsetBy: matchLength)

        var fillContainer = AttributeContainer()
        fillContainer.backgroundColor = fill
        result[startIdx..<endIdx].mergeAttributes(fillContainer)

        // The background above is clobbered on inline-code runs by the Boss inline style.
        // Mark those runs with a colored underline so the anchor stays visible. The
        // underline is applied to the whole span as well as code runs so it survives
        // regardless of which runs the inline style later restyles.
        var underlineContainer = AttributeContainer()
        underlineContainer.underlineStyle = Text.LineStyle(pattern: .solid, color: underline)
        result[startIdx..<endIdx].mergeAttributes(underlineContainer)

        highlightLog.debug(
            "\(label, privacy: .public): HIGHLIGHTED at chars \(startOffset, privacy: .public)..<\(startOffset + matchLength, privacy: .public) exact=\"\(preview, privacy: .public)\""
        )
    }

    /// Resolves a W3C `{exact, prefix, suffix}` anchor to a single range in the rendered
    /// plain text. Finds every whitespace-tolerant occurrence of `exact`, then — when there
    /// is more than one — picks the candidate whose surrounding text best matches the
    /// anchor's `prefix`/`suffix` context (preferring the earliest on a tie). Returns `nil`
    /// when `exact` no longer occurs at all.
    static func resolveRange(for anchor: CommentAnchor, in plain: String) -> Range<String.Index>? {
        guard !anchor.exact.isEmpty else { return nil }
        let candidates = flexibleMatchRanges(of: anchor.exact, in: plain)
        guard let first = candidates.first else { return nil }
        guard candidates.count > 1 else { return first }

        func contextScore(_ r: Range<String.Index>) -> Int {
            var score = 0
            if !anchor.prefix.isEmpty {
                let before = plain[plain.startIndex..<r.lowerBound]
                if before.hasSuffix(anchor.prefix) {
                    score += 2
                } else if let lastNonSpace = anchor.prefix.reversed().first(where: { !$0.isWhitespace }),
                          before.reversed().first(where: { !$0.isWhitespace }) == lastNonSpace {
                    score += 1
                }
            }
            if !anchor.suffix.isEmpty {
                let after = plain[r.upperBound..<plain.endIndex]
                if after.hasPrefix(anchor.suffix) {
                    score += 2
                } else if let firstNonSpace = anchor.suffix.first(where: { !$0.isWhitespace }),
                          after.first(where: { !$0.isWhitespace }) == firstNonSpace {
                    score += 1
                }
            }
            return score
        }

        var best = first
        var bestScore = contextScore(first)
        for candidate in candidates.dropFirst() {
            let score = contextScore(candidate)
            if score > bestScore {
                best = candidate
                bestScore = score
            }
        }
        return best
    }

    /// Returns every non-overlapping range in `plain` that matches `needle`, treating each
    /// run of whitespace in `needle` as matching one-or-more whitespace characters in
    /// `plain`. Leading/trailing whitespace in `needle` is ignored. Matches are returned in
    /// document order.
    ///
    /// For a single-token needle (no interior whitespace) this degenerates to an ordered,
    /// non-overlapping substring search.
    static func flexibleMatchRanges(of needle: String, in plain: String) -> [Range<String.Index>] {
        let trimmed = needle.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return [] }

        // Non-whitespace segments; interior whitespace runs become flexible gaps.
        let segments = trimmed.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        guard let first = segments.first else { return [] }
        let rest = segments.dropFirst()

        var results: [Range<String.Index>] = []
        var searchStart = plain.startIndex

        while let firstRange = plain.range(of: first, range: searchStart..<plain.endIndex) {
            var cursor = firstRange.upperBound
            var matched = true

            for seg in rest {
                // Require at least one whitespace character before the next segment.
                var wsCursor = cursor
                var whitespaceCount = 0
                while wsCursor < plain.endIndex, plain[wsCursor].isWhitespace {
                    wsCursor = plain.index(after: wsCursor)
                    whitespaceCount += 1
                }
                guard whitespaceCount >= 1, plain[wsCursor...].hasPrefix(seg) else {
                    matched = false
                    break
                }
                cursor = plain.index(wsCursor, offsetBy: seg.count)
            }

            if matched {
                results.append(firstRange.lowerBound..<cursor)
                searchStart = cursor
            } else {
                searchStart = firstRange.upperBound
            }
        }

        return results
    }
}
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        switch try c.decode(String.self, forKey: .type) {
        case "created":
            self = .created(
                taskId: try c.decode(String.self, forKey: .taskId),
                taskKind: try c.decode(String.self, forKey: .taskKind),
                addressedCommentIds: try c.decode([String].self, forKey: .addressedCommentIds),
                // The engine omits the key entirely when nothing was excluded
                // (`skip_serializing_if = "Vec::is_empty"`), which is the
                // common case.
                excludedCommentIds: try c.decodeIfPresent([String].self, forKey: .excludedCommentIds) ?? [],
                prUrl: try c.decodeIfPresent(String.self, forKey: .prUrl)
            )
        case "no_unresolved_comments":
            self = .noUnresolvedComments
        case "already_in_flight":
            self = .alreadyInFlight(taskId: try c.decode(String.self, forKey: .taskId))
        case "not_applicable":
            self = .notApplicable(reason: try c.decode(String.self, forKey: .reason))
        case let other:
            throw DecodingError.dataCorruptedError(
                forKey: .type, in: c, debugDescription: "unknown ReviseDocOutcome type: \(other)")
        }
    }
}

// MARK: - Plain-text projection + doc version

/// The renderer's plain-text projection of a markdown source, and the opaque
/// digest the engine stores as `doc_version`. Both the anchor-capture path and
/// the resolve-on-load path must compute the projection *identically* to what
/// [`HighlightingMarkdownParser`] paints against, so they share this helper —
/// it flattens the exact same Textual parse (`String(attributedString.characters)`)
/// the parser uses at `CommentHighlightingParser.swift:54-55`.
enum CommentProjection {
    /// Bump this whenever the projection algorithm changes so the engine can
    /// re-anchor everything once on a renderer upgrade (design § "Risks":
    /// "projection algorithm version"). Sent as `plain_text_projection_version`.
    static let version = 1

    /// Flatten `source` to the rendered plain text the user selects on. Falls
    /// back to the raw source if the Textual parse throws (degenerate but never
    /// crashes the viewer).
    @MainActor
    static func plainText(for source: String, baseURL: URL? = nil) -> String {
        if let attributed = try? AttributedStringMarkdownParser
            .markdown(baseURL: baseURL)
            .attributedString(for: source) {
            return String(attributed.characters)
        }
        return source
    }

    /// SHA-256 of the plain-text projection, hex-encoded and `sha256:`-prefixed.
    /// The engine treats this as opaque and only compares for equality.
    static func docVersion(forPlainText plainText: String) -> String {
        let digest = SHA256.hash(data: Data(plainText.utf8))
        let hex = digest.map { String(format: "%02x", $0) }.joined()
        return "sha256:\(hex)"
    }
}

enum MarkdownHeadingSections {
    /// A matched section spans from its heading's own line through the line
    /// immediately before the NEXT heading of *any* level — not the next
    /// heading of the *same* level. A revision brief's per-finding headings
    /// render as `### [severity] ...` directly after the boilerplate's `##
    /// HARD RULE ...` heading with no intervening heading in between; a
    /// same-level rule would treat those (deeper) finding headings as
    /// children of the H2 and fold them along with it — exactly the
    /// "findings must never collapse" outcome this function exists to
    /// avoid. Any-level is also simpler to reason about: "this heading's
    /// own prose, stopping at the very next heading" needs no notion of
    /// outline nesting at all.
    static func chunks(in source: String, collapsibleHeadings: Set<String>) -> [MarkdownDocumentChunk] {
        let headings = headingLines(in: source)
        guard !headings.isEmpty else { return [.plain(source)] }

        var chunks: [MarkdownDocumentChunk] = []
        var cursor = source.startIndex
        for (i, heading) in headings.enumerated() {
            if heading.lineRange.lowerBound > cursor {
                chunks.append(.plain(String(source[cursor..<heading.lineRange.lowerBound])))
            }
            let sectionEnd = (i + 1 < headings.count) ? headings[i + 1].lineRange.lowerBound : source.endIndex
            if collapsibleHeadings.contains(heading.text) {
                let body = String(source[heading.lineRange.upperBound..<sectionEnd])
                chunks.append(.collapsible(heading: heading.text, body: body))
            } else {
                chunks.append(.plain(String(source[heading.lineRange.lowerBound..<sectionEnd])))
            }
            cursor = sectionEnd
        }
        if cursor < source.endIndex {
            chunks.append(.plain(String(source[cursor...])))
        }
        return chunks
    }

    private struct HeadingLine {
        let text: String
        /// Spans the heading's own line, INCLUDING its trailing newline (or
        /// through end-of-source if the heading is the last line) — so a
        /// section's body starts exactly at `lineRange.upperBound`.
        let lineRange: Range<String.Index>
    }

    /// Skips fenced code blocks via the same fence toggle
    /// `MarkdownDocumentMeasure.containsTable` uses, so a `# comment` line
    /// inside a ``` fence isn't mistaken for a heading/section boundary —
    /// which would otherwise silently truncate a folded section and leave
    /// the remainder of its body rendered unfolded.
    private static func headingLines(in source: String) -> [HeadingLine] {
        var results: [HeadingLine] = []
        var lineStart = source.startIndex
        var inFencedCode = false
        while lineStart < source.endIndex {
            let newline = source[lineStart...].firstIndex(of: "\n")
            let contentEnd = newline ?? source.endIndex
            let lineEnd = newline.map(source.index(after:)) ?? source.endIndex
            let line = source[lineStart..<contentEnd]
            if MarkdownDocumentMeasure.isFenceDelimiter(line) {
                inFencedCode.toggle()
            } else if !inFencedCode, let text = headingText(in: line) {
                results.append(HeadingLine(text: text, lineRange: lineStart..<lineEnd))
            }
            lineStart = lineEnd
        }
        return results
    }

    /// A markdown ATX heading (`^ {0,3}#{1,6}[ \t]+...`) — CommonMark permits
    /// up to three leading spaces before the `#` markers, so an indented
    /// heading is still recognized; returns its trimmed text with the
    /// leading whitespace and `#` markers stripped, or `nil` if `line` isn't
    /// a heading.
    private static func headingText(in line: Substring) -> String? {
        var index = line.startIndex
        var leadingSpaces = 0
        while index < line.endIndex, line[index] == " ", leadingSpaces < 3 {
            leadingSpaces += 1
            index = line.index(after: index)
        }
        var level = 0
        while index < line.endIndex, line[index] == "#" {
            level += 1
            index = line.index(after: index)
        }
        guard level >= 1, level <= 6, index < line.endIndex, line[index] == " " || line[index] == "\t" else {
            return nil
        }
        let text = line[index...].trimmingCharacters(in: .whitespaces)
        return text.isEmpty ? nil : text
    }
}

/// One on-screen `StructuredText` for a document chunk. StructuredText
/// re-parses only when its markup string changes, so highlight updates
/// (comments, find) are expressed by tagging the markup with
/// `highlightGeneration` and stripping that tag inside the parser — never
/// by `.id()`, which would discard the parsed tree and reset scroll.
private struct DocumentStructuredText: View {
    let text: String
    let parser: any MarkupParser
    let highlightGeneration: Int
    var chunkIndex: Int = 0
    @Environment(\.markdownChunkAppearProbe) private var appearProbe

    var body: some View {
        StructuredText(
            MarkdownHighlightRefreshParser.tagged(text, generation: highlightGeneration),
            parser: MarkdownHighlightRefreshParser(inner: parser)
        )
        .textual.textSelection(.enabled)
        .frame(maxWidth: .infinity, alignment: .leading)
        .onAppear { appearProbe?.record(chunkIndex) }
    }
}

/// Restores the heading top-spacing that `BlockVStack` would have applied
/// between the previous section's last block and this chunk's first heading.
/// The enclosing `LazyVStack` uses spacing 0 so this modifier owns the whole
/// inter-chunk gap. Collapsible chunks already pad themselves; this is only
/// for `.plain` chunks after the first.
private struct MarkdownChunkTopSpacing: ViewModifier {
    let isFirst: Bool
    @Environment(\.markdownEditorialStyle) private var isEditorial
    @ScaledMetric(relativeTo: .body) private var bodySize: CGFloat = BossHeadingStyle.bodyPointSize

    func body(content: Content) -> some View {
        if isFirst {
            content
        } else {
            content.padding(.top, topGap)
        }
    }

    private var topGap: CGFloat {
        if isEditorial {
            return bodySize * MarkdownEditorialMetrics.editorialH2Spacing.top
        }
        return BossHeadingStyle.headingBlockSpacingTop
    }
}

/// StructuredText ignores parser-instance changes. A trailing nonce is
/// appended to the markup so `onChange(of: markup)` fires, then stripped
/// here so comment/search character offsets stay aligned with the real
/// source and the nonce never renders.
@MainActor
struct MarkdownHighlightRefreshParser: MarkupParser {
    let inner: any MarkupParser

    static let marker = "\n\n<!--boss-md-refresh:"

    func attributedString(for input: String) throws -> AttributedString {
        try inner.attributedString(for: Self.stripNonce(from: input))
    }

    static func stripNonce(from input: String) -> String {
        guard let range = input.range(of: marker, options: .backwards),
              input.hasSuffix("-->")
        else { return input }
        return String(input[..<range.lowerBound])
    }

    static func tagged(_ source: String, generation: Int) -> String {
        guard generation != 0 else { return source }
        return source + "\(marker)\(generation)-->"
    }
}

/// A heading-delimited section of a markdown document that folds behind a
/// disclosure affordance. Used only where a caller explicitly opts a
/// heading in via `MarkdownDocumentChrome.collapsedByDefaultHeadings`. The
/// heading text always renders as the summary label — so the section is
/// never invisible, and the collapsed state always names what's hidden
/// (never a bare triangle) — but deliberately at quiet, near-body
/// prominence rather than the source's real H2 size/weight: this is a
/// disclosure control the reader is meant to skip, not a section title
/// competing with the `###` findings nested beneath it. Styling it off the
/// heading level it happens to be built from (rather than shrinking H2s in
/// general) is the point — ordinary document H2s stay at full size.
private struct CollapsibleMarkdownSection: View {
    let heading: String
    let sectionBody: String
    let parser: any MarkupParser
    var highlightGeneration: Int = 0
    @Binding var isExpanded: Bool
    @Environment(\.markdownEditorialStyle) private var isEditorial
    @ScaledMetric(relativeTo: .body) private var bodySize: CGFloat = BossHeadingStyle.bodyPointSize

    private var hiddenLineCount: Int {
        max(sectionBody.split(separator: "\n", omittingEmptySubsequences: true).count, 1)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            toggleButton
            Rectangle()
                .fill(BossMarkdownPalette.hairline)
                .frame(height: 1)
            if isExpanded {
                DocumentStructuredText(
                    text: sectionBody,
                    parser: parser,
                    highlightGeneration: highlightGeneration,
                    chunkIndex: -1
                )
            }
        }
        .padding(.top, headingSpacing.top)
        .padding(.bottom, headingSpacing.bottom)
    }

    private var toggleButton: some View {
        Button {
            isExpanded.toggle()
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Image(systemName: isExpanded ? "chevron.down" : "chevron.right")
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(BossMarkdownPalette.muted)
                headingLabel
                Spacer(minLength: 8)
                Text(isExpanded ? "Collapse" : "Collapsed — \(hiddenLineCount) lines hidden. Click to expand.")
                    .font(.caption)
                    .foregroundStyle(BossMarkdownPalette.muted)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityIdentifier("markdown-collapsible-section-toggle")
        .accessibilityLabel(
            isExpanded
                ? "Collapse \(heading)"
                : "Expand \(heading) — \(hiddenLineCount) lines hidden"
        )
import Foundation

/// Resolves comment anchors once against the concatenated per-chunk
/// plain-text projection — the same corpora `MarkdownFindState` searches —
/// then hands each chunk only the anchors whose resolved range overlaps it.
///
/// `HighlightingMarkdownParser.resolveRange` picks exactly one best match
/// inside whatever string it is given. Feeding every chunk the full
/// document-wide anchor list therefore paints a recurring `exact` once per
/// section, and drops a selection that straddles a heading (it is in no
/// chunk's text). Resolving against the concatenation first restores the
/// pre-chunking "one span in the document" rule; a range that crosses a
/// heading is clipped so each overlapping chunk highlights its piece.
enum MarkdownCommentAnchorMap {
    private struct Projection {
        var plains: [String]
        var starts: [Int]
        var concat: String
    }

    struct ChunkAnchors: Equatable {
        var highlighted: [CommentAnchor]
        var flashing: CommentAnchor?

        static let empty = ChunkAnchors(highlighted: [], flashing: nil)
    }

    /// Memoizes `partition` across SwiftUI `body` evaluations. Held as a
    /// reference type so a cache hit does not write `@State`.
    @MainActor
    final class Cache {
        private var source: String?
        private var headings: Set<String>?
        private var highlighted: [CommentAnchor]?
        private var flashing: CommentAnchor?
        private var baseURL: URL?
        private var projection: Projection?
        private var value: [ChunkAnchors] = []

        func partition(
            source: String,
            headings: Set<String>,
            chunks: [MarkdownDocumentChunk],
            highlighted: [CommentAnchor],
            flashing: CommentAnchor?,
            baseURL: URL?
        ) -> [ChunkAnchors] {
            let projectionIsCurrent = self.source == source
                && self.headings == headings
                && self.baseURL == baseURL
                && projection?.plains.count == chunks.count
            if projectionIsCurrent,
               self.highlighted == highlighted,
               self.flashing == flashing {
                return value
            }
            self.source = source
            self.headings = headings
            self.highlighted = highlighted
            self.flashing = flashing
            self.baseURL = baseURL
            if !projectionIsCurrent {
                projection = MarkdownCommentAnchorMap.projection(for: chunks, baseURL: baseURL)
            }
            value = MarkdownCommentAnchorMap.assign(
                highlighted: highlighted,
                flashing: flashing,
                projection: projection!,
            )
            return value
        }
    }

    /// Builds the concatenated per-chunk projection and assigns each
    /// resolved range to the chunk(s) it overlaps. Anchors that miss the
    /// projection entirely are dropped (same silent no-op as the parser).
    @MainActor
    static func partition(
        chunks: [MarkdownDocumentChunk],
        highlighted: [CommentAnchor],
        flashing: CommentAnchor?,
        baseURL: URL?
    ) -> [ChunkAnchors] {
        guard !chunks.isEmpty else { return [] }
        return assign(
            highlighted: highlighted,
            flashing: flashing,
            projection: projection(for: chunks, baseURL: baseURL)
        )
    }

    @MainActor
    private static func projection(for chunks: [MarkdownDocumentChunk], baseURL: URL?) -> Projection {
        let plains = chunks.map { CommentProjection.plainText(for: $0.renderedText, baseURL: baseURL) }
        var starts: [Int] = []
        var cursor = 0
        for plain in plains {
            starts.append(cursor)
            cursor += plain.count
        }
        return Projection(plains: plains, starts: starts, concat: plains.joined())
    }

    @MainActor
    private static func assign(
        highlighted: [CommentAnchor],
        flashing: CommentAnchor?,
        projection: Projection
    ) -> [ChunkAnchors] {
        guard !highlighted.isEmpty || flashing != nil else {
            return Array(repeating: .empty, count: projection.plains.count)
        }

        var result = Array(repeating: ChunkAnchors.empty, count: projection.plains.count)
        for anchor in highlighted {
            assign(anchor, in: projection.concat, plains: projection.plains, starts: projection.starts, to: &result, flashing: false)
        }
        if let flashing {
            assign(flashing, in: projection.concat, plains: projection.plains, starts: projection.starts, to: &result, flashing: true)
        }
        return result
    }

    @MainActor
    private static func assign(
        _ anchor: CommentAnchor,
        in concat: String,
        plains: [String],
        starts: [Int],
        to result: inout [ChunkAnchors],
        flashing: Bool
    ) {
        guard let resolved = HighlightingMarkdownParser.resolveRange(for: anchor, in: concat) else { return }
        let match = characterOffsets(of: resolved, in: concat)
        for index in plains.indices {
            let chunkStart = starts[index]
            let chunkEnd = chunkStart + plains[index].count
            let overlapStart = max(match.lowerBound, chunkStart)
            let overlapEnd = min(match.upperBound, chunkEnd)
            guard overlapStart < overlapEnd else { continue }
            let local = (overlapStart - chunkStart)..<(overlapEnd - chunkStart)
            let clipped = clip(plains[index], to: local)
            guard isAnchorable(clipped) else { continue }
            if flashing {
                result[index].flashing = clipped
            } else {
                result[index].highlighted.append(clipped)
            }
        }
    }

    /// Rewrites `exact`/`prefix`/`suffix` into the chunk's own projection so
    /// the per-chunk parser can re-apply the highlight locally, including
    /// when only a slice of a heading-straddling selection lives here.
    private static func clip(_ plain: String, to local: Range<Int>) -> CommentAnchor {
        let exact = substring(plain, local)
        let prefixStart = max(0, local.lowerBound - 64)
        let suffixEnd = min(plain.count, local.upperBound + 64)
        let prefix = substring(plain, prefixStart..<local.lowerBound)
        let suffix = substring(plain, local.upperBound..<suffixEnd)
        return CommentAnchor(exact: exact, prefix: prefix, suffix: suffix)
    }

    static func isAnchorable(_ anchor: CommentAnchor) -> Bool {
        !anchor.exact.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private static func characterOffsets(of range: Range<String.Index>, in string: String) -> Range<Int> {
        let lower = string.distance(from: string.startIndex, to: range.lowerBound)
        let upper = string.distance(from: string.startIndex, to: range.upperBound)
        return lower..<upper
    }

    private static func substring(_ string: String, _ range: Range<Int>) -> String {
        let start = string.index(string.startIndex, offsetBy: range.lowerBound)
        let end = string.index(string.startIndex, offsetBy: range.upperBound)
        return String(string[start..<end])
    }
}

    **Review summary:** One bug found.
    """

